    "3-21": { status: 'NP', statusFull: "Parilia", deity: "Pales", deityDesc: "Diosa de los pastores.", festivalName: "Parilia / Natalis Romae", festivalDesc: "Festival pastoral de purificación de los rebaños, considerado tradicionalmente como el aniversario de la fundación mítica de Roma (Dies Natalis)." },
    "3-22": { status: 'N', statusFull: "Dies Nefastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "3-23": { status: 'F', statusFull: "Fastus", deity: "Júpiter / Venus Erucina", deityDesc: "Júpiter como protector principal del vino (primario en la República); Venus Erucina, de origen siciliano.", festivalName: "Vinalia Priora", festivalDesc: "Primera celebración anual del vino. El vino del año anterior era abierto y se ofrecían las libaciones a Júpiter." },
    "3-24": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "3-25": { status: 'NP', statusFull: "Robigalia", deity: "Robigo", deityDesc: "Deidad de la roya y el mildiu de los cereales.", festivalName: "Robigalia", festivalDesc: "El flamen Quirinalis presidía el rito en la Via Claudia (al quinto miliario de Roma). Se sacrificaban dos víctimas: un perro de pelo rojizo y una oveja, ofrecidas a Robigus o Robigo para prevenir la roya (robigo) que destruía el trigo en ciernes. Las entrañas se quemaban en honor a la deidad." },
    "3-26": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "3-27": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "3-28": { status: 'NP', statusFull: "Floralia", deity: "Flora", deityDesc: "Diosa de las flores.", festivalName: "Floralia", festivalDesc: "Inicio de los Ludi Florales, fiestas bulliciosas y alegres celebrando la fertilidad de las flores en desarrollo." },
    "3-29": { status: 'C', statusFull: "Dies Comitialis", deity: "Flora", deityDesc: "Diosa de las flores.", festivalName: "Floralia", festivalDesc: "Continúan los juegos de Flora." },
    "3-30": { status: 'C', statusFull: "Dies Comitialis", deity: "Flora", deityDesc: "Diosa de las flores.", festivalName: "Floralia", festivalDesc: "Prosiguen los juegos licenciosos y celebraciones al aire libre de Flora." },

