    "4-1": { status: 'F', statusFull: "Fastus", deity: "Bona Dea / Lares Praestites", deityDesc: "Diosa buena y guardianes cívicos.", festivalName: "Dedicaciones / Floralia", festivalDesc: "Ofrendas a los Lares de la ciudad y aniversario del templo de la Bona Dea. Continúan los Ludi de Flora." },
    "4-2": { status: 'F', statusFull: "Dies Fastus", deity: "Flora", deityDesc: "Diosa de las flores.", festivalName: "Floralia", festivalDesc: "Continuación de las festividades de Flora." },
