    "4-9": { status: 'N', statusFull: "Nefastus", deity: "Lemures", deityDesc: "Espíritus de los muertos.", festivalName: "Lemuria", festivalDesc: "Primer día de los ritos arcaicos de propiciación familiar. A medianoche, el paterfamilias se levantaba descalzo, hacía la señal apotropaica con los dedos y recorría la casa escupiendo habas negras de su boca nueve veces hacia atrás sin mirar, mientras repetía: 'Haec ego mitto; his redimo meque meosque fabis'. Los Lemures recogían simbólicamente las habas. El rito se repetía con golpes de bronce y la fórmula 'Manes exite paterni'." },
    "4-10": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "4-11": { status: 'N', statusFull: "Nefastus", deity: "Lemures", deityDesc: "Espíritus de los muertos.", festivalName: "Lemuria", festivalDesc: "Segundo día de ritos de expiación a los muertos." },
    "4-12": { status: 'NP', statusFull: "Ludi Martiales", deity: "Mars Ultor", deityDesc: "Marte Vengador.", festivalName: "Dedicación del Templo de Marte Ultor", festivalDesc: "Juegos en el Circo que conmemoran la dedicación del templo de Marte en el foro de Augusto (2 a.C.)." },
    "4-13": { status: 'N', statusFull: "Nefastus", deity: "Lemures", deityDesc: "Espíritus de los muertos.", festivalName: "Lemuria", festivalDesc: "Último día de ritos nocturnos de la Lemuria." },
    "4-14": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica.", festivalName: "Ritos de los Argei", festivalDesc: "Procesión sagrada. Las vírgenes vestales y el pontífice arrojaban al Tíber veinticuatro (o veintisiete) efigies de junco (scirpea simulacra) en forma humana llamadas Argei, recogidas en las capillas homónimas repartidas por las colinas de Roma. La fecha exacta es incierta: Scullard da el 14 de mayo, Fowler el 15." },
    "4-15": { status: 'NP', statusFull: "Idus / Mercuralia", deity: "Mercurio / Júpiter", deityDesc: "Dios del comercio / Dios supremo.", festivalName: "Mercuralia", festivalDesc: "Día de los Idus. Los comerciantes pedían a Mercurio protección para sus negocios y perdón por las transgresiones comerciales." },
    "4-16": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "4-17": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "4-18": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "4-19": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "4-20": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "4-21": { status: 'NP', statusFull: "Agonalia", deity: "Vediovis", deityDesc: "Antigua deidad.", festivalName: "Agonalia", festivalDesc: "Día de sacrificio especial consagrado a Vediovis." },
    "4-22": { status: 'N', statusFull: "Dies Nefastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "4-23": { status: 'NP', statusFull: "Tubilustrium", deity: "Vulcano", deityDesc: "Dios del fuego y la forja.", festivalName: "Tubilustrium", festivalDesc: "Segunda purificación anual de las trompetas sagradas (tubae) en el Atrium Sutorium. Las trompetas rituales empleadas en el culto público eran purificadas con fórmulas y ofrendas. El Tubilustrium no tenía deidad patrona propia; la Feriae Volcano es una fiesta separada atestiguada en los mismos Idus." },
    "4-24": { status: 'F', statusFull: "QRCF", deity: "Ninguna", deityDesc: "Rito del rey sagrado.", festivalName: "Quando Rex Comitiavit Fas", festivalDesc: "El Rex Sacrorum completaba sus deberes religiosos." },
    "4-25": { status: 'C', statusFull: "Dies Comitialis", deity: "Fortuna Primigenia", deityDesc: "Fortuna original.", festivalName: "Dedicación del Templo de Fortuna Primigenia", festivalDesc: "Celebración cívica de la Fortuna Original de la colina Quirinal." },
    "4-26": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "4-27": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
