    "4-29": { status: 'C', statusFull: "Dies Comitialis", deity: "Marte / Ceres", deityDesc: "Dios de la guerra y protector de los campos; diosa del cereal.", festivalName: "Ambarvalia", festivalDesc: "Feriae conceptivae. Purificación de las tierras agrícolas marchando a lo largo de los límites con víctimas sacrificiales (suovetaurilia)." },
    "4-30": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
