    // --- IUNIUS (JUNE) ---
    "5-1": { status: 'N', statusFull: "Nefastus", deity: "Carna / Juno Moneta", deityDesc: "Diosas protectoras.", festivalName: "Kalendae Fabariae", festivalDesc: "Sacrificio de habas a Carna, protectora de la vitalidad del cuerpo. También aniversario del templo de Juno Moneta." },
    "5-2": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "5-3": { status: 'C', statusFull: "Dies Comitialis", deity: "Bellona", deityDesc: "Diosa de la guerra.", festivalName: "Dedicación del Templo de Bellona", festivalDesc: "Aniversario de la dedicación del templo en el Campo de Marte (296 a.C.)." },
    "5-4": { status: 'C', statusFull: "Dies Comitialis", deity: "Hercules Custos", deityDesc: "Hércules Guardián.", festivalName: "Dedicación del Templo de Hércules", festivalDesc: "Dedicación del templo de Hercules Custos." },
    "5-5": { status: 'N', statusFull: "Nefastus", deity: "Semo Sancus Dius Fidius", deityDesc: "Dios de los juramentos.", festivalName: "Dedicación del Templo de Dius Fidius", festivalDesc: "Fiesta y conmemoración de Semo Sancus, garante de la fides (lealtad y juramentos)." },
    "5-6": { status: 'N', statusFull: "Dies Nefastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "5-7": { status: 'N', statusFull: "Dies Nefastus", deity: "Vulcanus", deityDesc: "Dios del fuego y la forja.", festivalName: "Ludi Piscatorii", festivalDesc: "Los pescadores del Tíber celebraban juegos y ofrecían su captura del día arrojándola a las llamas en honor a Vulcano en la ribera del río. La ofrenda de peces al fuego actuaba como sustituto de las almas que el fuego del verano podría arrebatar." },
    "5-8": { status: 'N', statusFull: "Dies Nefastus", deity: "Mens", deityDesc: "Diosa del pensamiento y el intelecto.", festivalName: "Dedicación del Templo de Mens", festivalDesc: "Aniversario del templo de Mens, dedicado tras desastres militares para devolver el intelecto a Roma." },
    "5-9": { status: 'N', statusFull: "Nefastus", deity: "Vesta", deityDesc: "Diosa del fuego sagrado del estado.", festivalName: "Vestalia", festivalDesc: "Día central de la Vestalia: el penus Vestae (santuario interior del templo de Vesta) había sido abierto el 7 de junio (Vesta Aperitur) y permanecía accesible a las matronas hasta el 15 de junio. El 9 de junio era la festividad principal, en que los burros de los panaderos eran adornados con panes y guirnaldas en agradecimiento al molino que Vesta también protegía." },
    "5-10": { status: 'N', statusFull: "Dies Nefastus", deity: "Vesta", deityDesc: "Diosa del fuego del hogar.", festivalName: "Vestalia", festivalDesc: "Continuación de los ritos privados en el santuario del Foro." },
    "5-11": { status: 'N', statusFull: "Nefastus", deity: "Mater Matuta", deityDesc: "Antigua diosa de la luz matinal.", festivalName: "Matralia", festivalDesc: "Fiesta de las matronas. Se rogaba a la diosa que protegiera a los hijos de sus hermanas por encima de los propios." },
    "5-12": { status: 'N', statusFull: "Dies Nefastus", deity: "Vesta", deityDesc: "Diosa del fuego.", festivalName: "Vestalia", festivalDesc: "Prosiguen los ritos lustrales." },
    "5-13": { status: 'NP', statusFull: "Idus", deity: "Minerva / Júpiter", deityDesc: "Diosa de los artesanos y Júpiter.", festivalName: "Quinquatrus Minusculae", festivalDesc: "La 'Pequeña Quinquatría', festival particular para los flautistas sagrados (tibicines)." },
    "5-14": { status: 'N', statusFull: "Dies Nefastus", deity: "Vesta", deityDesc: "Diosa del fuego sagrado.", festivalName: "Vestalia", festivalDesc: "Último día de labores previas a la apertura ritual total." },
    "5-15": { status: 'N', statusFull: "Nefastus", deity: "Vesta", deityDesc: "Diosa del fuego sagrado.", festivalName: "Quando Stercum Delatum Fas", festivalDesc: "Fin oficial de la limpieza del Penus Vestae. Las cenizas purgadas eran arrastradas al Tíber o a lugares sagrados." },
    "5-16": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "5-17": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "5-18": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "5-19": { status: 'C', statusFull: "Dies Comitialis", deity: "Minerva", deityDesc: "Diosa de las artes y oficios.", festivalName: "Dedicación Templo Minerva", festivalDesc: "Aniversario del templo de Minerva en el monte Aventino." },
    "5-20": { status: 'C', statusFull: "Dies Comitialis", deity: "Summanus", deityDesc: "Dios de los relámpagos nocturnos.", festivalName: "Summanalia", festivalDesc: "Sacrificio de expiación a Summanus. Se ofrecían pasteles de harina con forma de ruedas." },
    "5-21": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
