    "5-23": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "5-24": { status: 'C', statusFull: "Dies Comitialis", deity: "Fortuna", deityDesc: "Diosa de la suerte y el azar.", festivalName: "Fors Fortuna", festivalDesc: "Festividad popular a las afueras de la ciudad. El pueblo descendía en barcas por el Tíber celebrando sin restricciones." },
    "5-25": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "5-26": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "5-27": { status: 'C', statusFull: "Dies Comitialis", deity: "Jupiter Stator", deityDesc: "Júpiter el que detiene la huida.", festivalName: "Dedicación del Templo de Jupiter Stator", festivalDesc: "Celebración del título marcial de Júpiter establecido tras las guerras en el pasado arcaico de Roma." },
    "5-28": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "5-29": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "5-30": { status: 'C', statusFull: "Dies Comitialis", deity: "Hercules Musarum", deityDesc: "Hércules con las Musas.", festivalName: "Dedicación del Templo de Hercules Musarum", festivalDesc: "Dedicación del Templo erigido en el Circo Flaminio." },

