    "6-1": { status: 'N', statusFull: "Nefastus", deity: "Juno / Felicitas", deityDesc: "Reina de los dioses y diosa de la felicidad cívica.", festivalName: "Kalendae de Julio", festivalDesc: "Observancias ordinarias de las calendas." },
    "6-2": { status: 'N', statusFull: "Dies Nefastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
