    "6-4": { status: 'N', statusFull: "Dies Nefastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "6-5": { status: 'NP', statusFull: "Poplifugia", deity: "Júpiter", deityDesc: "Dios supremo.", festivalName: "Poplifugia", festivalDesc: "La 'Huida del Pueblo'. Ritos misteriosos de origen antiquísimo vinculados a asaltos de pueblos vecinos en los albores de Roma." },
    "6-6": { status: 'N', statusFull: "Dies Nefastus", deity: "Apolo", deityDesc: "Dios de la música, sanación y profecía.", festivalName: "Ludi Apollinares", festivalDesc: "Comienzo oficial de los juegos escénicos y cívicos dedicados al dios Apolo." },
    "6-7": { status: 'N', statusFull: "Nefastus", deity: "Juno Caprotina", deityDesc: "Juno del cabrahígo.", festivalName: "Nonae Caprotinae", festivalDesc: "Fiesta de las sirvientas con batallas simuladas y banquetes. Coincide con la continuación de los Ludi Apollinares." },
    "6-8": { status: 'NP', statusFull: "Dies Nefastus", deity: "Apolo", deityDesc: "Dios de la curación.", festivalName: "Ludi Apollinares", festivalDesc: "Días consagrados al teatro y ritos a Apolo." },
    "6-9": { status: 'NP', statusFull: "Dies Nefastus", deity: "Apolo", deityDesc: "Dios de la curación.", festivalName: "Ludi Apollinares", festivalDesc: "Prosiguen los juegos de Apolo." },
    "6-10": { status: 'C', statusFull: "Dies Comitialis", deity: "Apolo", deityDesc: "Dios de la curación.", festivalName: "Ludi Apollinares", festivalDesc: "Continuación de los eventos teatrales." },
    "6-11": { status: 'C', statusFull: "Dies Comitialis", deity: "Apolo", deityDesc: "Dios de la curación.", festivalName: "Ludi Apollinares", festivalDesc: "Prosiguen los espectáculos públicos de los Ludi." },
    "6-12": { status: 'C', statusFull: "Dies Comitialis", deity: "Apolo", deityDesc: "Dios de la curación.", festivalName: "Ludi Apollinares", festivalDesc: "Penúltimo día de las festividades en honor a Apolo." },
    "6-13": { status: 'C', statusFull: "Comitialis", deity: "Apolo", deityDesc: "Dios de la curación.", festivalName: "Fin de los Ludi Apollinares", festivalDesc: "Conclusión de los Ludi dedicados a alejar plagas de la urbe." },
    "6-14": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "6-15": { status: 'NP', statusFull: "Idus", deity: "Cástor y Pólux / Júpiter", deityDesc: "Los Dióscuros.", festivalName: "Transvectio Equitum", festivalDesc: "Gran parada militar y religiosa en honor a los Dióscuros, revistiendo a la clase ecuestre (equites) de la República e Imperio." },
    "6-16": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "6-17": { status: 'C', statusFull: "Dies Comitialis", deity: "Honos y Virtus", deityDesc: "Dioses gemelos del Honor y la Virtud militar.", festivalName: "Dedicación del Templo de Honos", festivalDesc: "Celebración cívica asociada a la deidad militar del honor." },
    "6-18": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día infausto cívico.", festivalName: "Dies Alliensis (Dies Ater)", festivalDesc: "Día de luto cívico que conmemora dos desastres romanos: la derrota de los Fabios en el río Cremera a manos de los Veyentes (479 a.C.) y la aplastante derrota frente a los galos en la batalla del Alia (390 o 387 a.C.), que dejó Roma abierta al saqueo. Por este doble carácter se le conoce también como 'Dies Alliae et Fabiorum'." },
    "6-19": { status: 'NP', statusFull: "Lucaria", deity: "Deidades del Bosque", deityDesc: "Protectores arbolados.", festivalName: "Lucaria", festivalDesc: "Fiestas purificadoras de los bosques sagrados donde los romanos se ocultaron tras el desastre del Alia." },
    "6-20": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "6-21": { status: 'NP', statusFull: "Lucaria II", deity: "Deidades del Bosque", deityDesc: "Protectores arbolados.", festivalName: "Lucaria", festivalDesc: "Segundo día de ritos en las arboledas sagradas romanas." },
    "6-22": { status: 'C', statusFull: "Dies Comitialis", deity: "Concordia", deityDesc: "Diosa de la armonía.", festivalName: "Dedicación del Templo de Concordia", festivalDesc: "Aniversario de otra fundación del templo." },
    "6-23": { status: 'NP', statusFull: "Neptunalia", deity: "Neptuno", deityDesc: "Dios de las aguas dulces y el mar.", festivalName: "Neptunalia", festivalDesc: "Fiesta del verano extremo buscando la intervención de las aguas divinas frente a las sequías. La gente construía cobertizos de ramas frondosas." },
    "6-24": { status: 'N', statusFull: "Dies Nefastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "6-25": { status: 'NP', statusFull: "Furrinalia", deity: "Furrina", deityDesc: "Arcaica diosa de las fuentes y manantiales.", festivalName: "Furrinalia", festivalDesc: "Se ofrecían sacrificios a la olvidada diosa Furrina en su santuario del monte Janículo." },
    "6-26": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
