    "7-2": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "7-3": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Ritos menores.", festivalName: "Supplicia Canum", festivalDesc: "Se castigaba ritualmente a los perros por no haber ladrado cuando los galos asediaron el Capitolio en el pasado lejano." },
