    "7-13": { status: 'NP', statusFull: "Idus", deity: "Diana", deityDesc: "Diosa de los bosques y la luna.", festivalName: "Dianae in Aventino", festivalDesc: "Dies natalis del templo de Diana en el Aventino, dedicado según la tradición por Servio Tulio para unir a los latinos bajo Roma. Las mujeres y los esclavos lo veneraban con especial devoción. El culto en el lago Nemi (Nemoralia) es un observancia distinta que coincide aproximadamente con esta fecha." },
