    "7-21": { status: 'NP', statusFull: "Nefastus Publicus", deity: "Consus", deityDesc: "Dios de los silos subterráneos.", festivalName: "Consualia", festivalDesc: "Apertura ceremonial del altar subterráneo de Consus en el Circo Máximo y carreras de mulas coronadas con flores." },
    "7-22": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "7-23": { status: 'NP', statusFull: "Vulcanalia", deity: "Vulcano", deityDesc: "Dios del fuego devorador.", festivalName: "Vulcanalia", festivalDesc: "Rito para proteger los campos maduros del fuego del final del verano. Se arrojaban peces y presas menores a las hogueras a modo de sustituto." },
    "7-24": { status: 'C', statusFull: "Dies Comitialis", deity: "Manes", deityDesc: "Espíritus del inframundo.", festivalName: "Mundus Patet", festivalDesc: "Primera de las tres fechas del año en que el 'Mundo' (fosa ritual del más allá) quedaba abierto, siendo un día nefasto para cualquier labor militar o política mayor." },
