    "8-4": { status: 'C', statusFull: "Dies Comitialis", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalDesc: "Día previo al inicio republicano de los Ludi Romani; el comienzo atestiguado en la república es el 5 de septiembre (Nonae). El 4 de septiembre es un inicio imperial de era tardía inferido por Mommsen, no confirmado por los fasti republicanos." },
    "8-5": { status: 'F', statusFull: "Nonae", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Romani", festivalDesc: "Días de celebraciones y obras teatrales de los Juegos Romanos." },
    "8-6": { status: 'F', statusFull: "Dies Fastus", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Romani", festivalDesc: "Continúan las actividades escénicas de los Juegos." },
    "8-7": { status: 'C', statusFull: "Dies Comitialis", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Romani", festivalDesc: "Prosiguen los juegos en la ciudad." },
    "8-8": { status: 'C', statusFull: "Dies Comitialis", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Romani", festivalDesc: "Obras teatrales sufragadas por ediles para disfrute del pueblo romano." },
