    "8-11": { status: 'C', statusFull: "Dies Comitialis", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Romani", festivalDesc: "Día de espectáculos lúdicos y esparcimiento popular." },
    "8-12": { status: 'C', statusFull: "Dies Comitialis", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Romani", festivalDesc: "Última jornada reservada primariamente a espectáculos escénicos." },
    "8-13": { status: 'NP', statusFull: "Idus", deity: "Júpiter, Juno, Minerva", deityDesc: "La Tríada Capitolina.", festivalName: "Epulum Jovis", festivalDesc: "Banquete central de los Idus consagrado a la Tríada Capitolina; los senadores comían ritualmente junto a imágenes de los dioses." },
    "8-14": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Las fuentes no nombran deidad patrona para este día.", festivalName: "Equorum Probatio", festivalDesc: "Revista e inspección (equorum probatio) de la caballería legionaria ante los censores durante los Ludi Romani. Los jinetes de la clase ecuestre desfilaban en orden de tribu por el Foro engalanados con coronas de olivo. Se trata de una revisión cívico-militar, no de un rito de purificación." },
    "8-15": { status: 'C', statusFull: "Comitialis", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Romani", festivalDesc: "Comienzo del traslado de las festividades a las carreras del Circo Máximo." },
    "8-16": { status: 'C', statusFull: "Dies Comitialis", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Romani", festivalDesc: "Múltiples carreras de carros frente a decenas de miles de asistentes en el Circo." },
    "8-17": { status: 'C', statusFull: "Dies Comitialis", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Romani", festivalDesc: "Prosiguen las carreras organizadas por facciones ecuestres." },
