    "9-4": { status: 'C', statusFull: "Dies Comitialis", deity: "Ceres", deityDesc: "Diosa de la tierra cultivada.", festivalName: "Ieiunium Cereris", festivalDesc: "Día de ayuno religioso instaurado bajo la República en respuesta a prodigios severos y en honor a Ceres." },
    "9-5": { status: 'C', statusFull: "Dies Comitialis", deity: "Augusto / Manes", deityDesc: "El emperador divinizado y espíritus del inframundo.", festivalName: "Ludi Augustales / Mundus Patet", festivalDesc: "Inicio de los juegos imperiales en honor a Augusto. También segunda de las tres aperturas anuales del Mundus (fosa ritual al más allá): los espíritus de los muertos vagan libremente por la ciudad." },
    "9-6": { status: 'C', statusFull: "Dies Comitialis", deity: "Augusto", deityDesc: "Divus Augustus.", festivalName: "Ludi Augustales", festivalDesc: "Juegos del Augusto." },
    "9-7": { status: 'F', statusFull: "Nonae", deity: "Júpiter Fulgur / Juno Curitis", deityDesc: "Júpiter del rayo y Juno Curitis, epíteto falisco atestiguado en el Campo de Marte.", festivalName: "Ritos a Júpiter", festivalDesc: "Día tradicional de apaciguamiento estacional al dios de los rayos." },
    "9-8": { status: 'F', statusFull: "Dies Fastus", deity: "Augusto", deityDesc: "Divus Augustus.", festivalName: "Ludi Augustales", festivalDesc: "Juegos cívicos imperiales." },
    "9-9": { status: 'C', statusFull: "Dies Comitialis", deity: "Genius Publicus / Fausta Felicitas / Venus Victrix", deityDesc: "El Genio del pueblo romano, la Felicidad propicia y Venus Victoriosa.", festivalName: "Dedicación y Juegos", festivalDesc: "Celebración del aniversario de los Genios protectores del pueblo, entrelazada con Ludi." },
    "9-10": { status: 'C', statusFull: "Dies Comitialis", deity: "Juno Moneta", deityDesc: "Juno la Consejera.", festivalName: "Ludi Augustales", festivalDesc: "Continuación de juegos, así como conmemoración de templos atávicos." },
    "9-11": { status: 'NP', statusFull: "Meditrinalia", deity: "Meditrina / Júpiter", deityDesc: "Diosa de la curación rústica.", festivalName: "Meditrinalia", festivalDesc: "Festividad agraria para probar la vendimia. Se bebía vino mezclando mosto fresco con vino viejo como curativo de salud." },
    "9-12": { status: 'C', statusFull: "Dies Comitialis", deity: "Augusto", deityDesc: "Divus Augustus.", festivalName: "Fin Ludi Augustales", festivalDesc: "Conclusión de los juegos en honor al primer emperador." },
    "9-13": { status: 'NP', statusFull: "Dies Nefastus Publicus", deity: "Fons", deityDesc: "Dios de los manantiales.", festivalName: "Fontinalia", festivalDesc: "Fiesta y honores a los pozos y fuentes, engalanando todos los manantiales cívicos con guirnaldas florales de otoño." },
    "9-14": { status: 'EN', statusFull: "Dies Endotercissus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "9-15": { status: 'NP', statusFull: "Idus", deity: "Marte", deityDesc: "Dios guerrero.", festivalName: "Equus October", festivalDesc: "Carrera de cuadrigas solemne que señalaba el cierre de la temporada bélica en el Campo de Marte. El caballo derecho del equipo ganador era sacrificado al instante con una lanza por el sacerdote. Su cabeza era luego disputada entre los habitantes de la Via Sacra y los del barrio de la Subura para colgarla en sus respectivos lugares. La cola del caballo era llevada a toda prisa a la Regia para que su sangre goteara sobre el hogar sagrado." },
    "9-16": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
