    "9-19": { status: 'NP', statusFull: "Armilustrium", deity: "Marte", deityDesc: "Dios guerrero.", festivalName: "Armilustrium", festivalDesc: "Clausura ceremonial de las campañas militares del año. Las armas de las legiones eran purificadas y devueltas a depósito de forma sagrada." },
    "9-20": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "9-21": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
