    "9-26": { status: 'C', statusFull: "Dies Comitialis", deity: "Victoria", deityDesc: "Diosa de la Victoria.", festivalName: "Ludi Victoriae Sullanae", festivalDesc: "Comienzo de los juegos republicanos conmemorando la victoria de Lucio Cornelio Sila." },
    "9-27": { status: 'C', statusFull: "Dies Comitialis", deity: "Victoria", deityDesc: "Diosa de la Victoria.", festivalName: "Ludi Victoriae Sullanae", festivalDesc: "Representaciones del éxito armado." },
