    // --- NOVEMBER (NOVEMBER) ---
    "10-1": { status: 'F', statusFull: "Fastus", deity: "Victoria", deityDesc: "Diosa de la Victoria, deidad tutelar de los Ludi Victoriae Sullanae.", festivalName: "Ludi Victoriae Sullanae (Fin)", festivalDesc: "Jornada de clausura de los Ludi Victoriae Sullanae con los Circenses (carreras de carros en el Circo Máximo). Estos juegos fueron votados por Lucio Cornelio Sila tras su victoria militar y se celebraban desde el 26 de octubre hasta el 1 de noviembre." },
    "10-2": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "10-3": { status: 'C', statusFull: "Dies Comitialis", deity: "Júpiter", deityDesc: "Rey de los dioses." },
    "10-4": { status: 'C', statusFull: "Dies Comitialis", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Plebeii", festivalDesc: "Inician los históricos Juegos de la Plebe (PR. NON. NOV.), una afirmación de la identidad y libertades plebeyas. Los ediles plebeyos organizaban espectáculos teatrales y más adelante carreras en el circo." },
    "10-5": { status: 'F', statusFull: "Nonae", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Plebeii", festivalDesc: "Siguen las obras de teatro en las urbes." },
    "10-6": { status: 'NP', statusFull: "Dies Nefastus Publicus", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Plebeii", festivalDesc: "Prosigue la actividad teatral de los Ludi." },
    "10-7": { status: 'NP', statusFull: "Dies Nefastus Publicus", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Plebeii", festivalDesc: "Más celebraciones lúdicas del estado." },
    "10-8": { status: 'C', statusFull: "Comitialis (dies religiosus)", deity: "Divinidades ctónicas", deityDesc: "Las potencias del mundo subterráneo; ninguna deidad específica nombrada en las fuentes.", festivalName: "Mundus Patet", festivalDesc: "Tercera y última apertura anual del mundus (fosa o bóveda ritual en el Comitium). La secuencia completa es: 24 de agosto (primera apertura), 5 de octubre (segunda) y 8 de noviembre (tercera y definitiva). En cada una, las potencias del más allá podían ascender brevemente al mundo de los vivos; ninguna actividad militar, naval o pública grave debía emprenderse." },
    "10-9": { status: 'NP', statusFull: "Dies Nefastus Publicus", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Plebeii", festivalDesc: "Continúa la devoción cívica teatral a Júpiter Plebeyo." },
    "10-10": { status: 'NP', statusFull: "Dies Nefastus Publicus", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Plebeii", festivalDesc: "Días festivos ininterrumpidos organizados para la población." },
    "10-11": { status: 'NP', statusFull: "Dies Nefastus Publicus", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Plebeii", festivalDesc: "El programa festivo continúa." },
    "10-12": { status: 'NP', statusFull: "Dies Nefastus Publicus", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Plebeii", festivalDesc: "Finaliza mayormente el circuito escénico plebeyo, a las puertas de las carreras." },
    "10-13": { status: 'NP', statusFull: "Idus", deity: "Júpiter / Feronia", deityDesc: "Júpiter y la diosa itálica Feronia, honrada en el Campo.", festivalName: "Epulum Jovis / Feroniae in Campo", festivalDesc: "Importante banquete divino para Júpiter a expensas de la magistratura de la plebe. En los Idus también se celebraba en el Campo el culto de Feronia, diosa protectora itálica de los libertos y las tierras feraces." },
    "10-14": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Las fuentes no atribuyen deidad patrona a este día.", festivalName: "Equorum Probatio", festivalDesc: "Otra revisión militar ecuestre ritual celebrada durante las pausas del festival." },
    "10-15": { status: 'NP', statusFull: "Dies Nefastus Publicus", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Plebeii", festivalDesc: "Prosiguen los Ludi Plebeii con espectáculos circenses organizados por los ediles plebeyos." },
    "10-16": { status: 'C', statusFull: "Dies Comitialis", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Ludi Plebeii", festivalDesc: "Carreras ecuestres y carreras de carros frenéticas bajo techo del Circo Flaminio o Máximo." },
    "10-17": { status: 'C', statusFull: "Dies Comitialis", deity: "Júpiter", deityDesc: "Rey de los dioses.", festivalName: "Fin Ludi Plebeii", festivalDesc: "Conclusión de los Ludi Plebeii." },
