    "11-1": { status: 'N', statusFull: "Nefastus", deity: "Juno", deityDesc: "Reina divina.", festivalName: "Kalendae", festivalDesc: "Honras ordinarias de Calendas." },
    "11-2": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "11-3": { status: 'NP', statusFull: "Dies Nefastus Publicus", deity: "Bona Dea", deityDesc: "Diosa exclusiva femenina.", festivalName: "Ritos de la Bona Dea", festivalDesc: "Ceremonia nocturna celebrada en la domus de un magistrado cum imperio, presidida por su esposa o la Vestal Mayor. Asistían exclusivamente mujeres de rango senatorial y las Vestales. El vino era la ofrenda central, pero por convención ritual se le llamaba 'leche' (lac) y el recipiente se denominaba 'vaso de miel' (mellarium); prohibir pronunciar la palabra 'vino' era parte del rito. Los hombres tenían vedado el acceso, y toda imagen masculina era cubierta." },
    "11-4": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "11-5": { status: 'F', statusFull: "Nonae", deity: "Fauno", deityDesc: "Deidad agreste y pastoral.", festivalName: "Faunalia Rustica", festivalDesc: "Ceremonias agrarias alegres dedicadas a Fauno para el resguardo de ganados durante el invierno incipiente." },
    "11-6": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "11-7": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "11-8": { status: 'C', statusFull: "Dies Comitialis", deity: "Tiberinus / Gaia", deityDesc: "Dios del río Tíber y Gaia, la Tierra.", festivalName: "Tiberinalia", festivalDesc: "Se honraba el aniversario del Templo del Dios Tíber en la isla Tiberina." },
    "11-9": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "11-10": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "11-11": { status: 'NP', statusFull: "Agonalia", deity: "Sol Indiges", deityDesc: "El Sol divino autóctono.", festivalName: "Agonalia / Septimontium", festivalDesc: "Expiación mediante sacrificio y celebración paralela en honor de las míticas primeras siete elevaciones geográficas que integraron la arcaica Roma." },
    "11-12": { status: 'EN', statusFull: "Dies Endotercissus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "11-13": { status: 'NP', statusFull: "Idus", deity: "Tellus / Ceres", deityDesc: "La Madre Tierra (primaria, dies natalis del templo) y Ceres (lectisternium).", festivalName: "Dies Natalis Telluris / Lectisternium Cereris", festivalDesc: "Se ofrecían las primicias agrícolas a la deidad dispuesta en lechos ceremoniales agradeciendo las buenas reservas vitales conservadas." },
    "11-14": { status: 'F', statusFull: "Dies Fastus", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "11-15": { status: 'NP', statusFull: "Consualia", deity: "Consus", deityDesc: "Dios custodio de los silos subterráneos de grano.", festivalName: "Consualia de Invierno", festivalDesc: "Segunda Consualia del año, celebrada el 15 de diciembre. A diferencia de la Consualia de agosto (21 de agosto), en que se descubría el altar subterráneo de Consus en el Circo Máximo, la consualia invernal es una festividad de reposo y gratitud agraria: los caballos (equi) y las mulas (muli) eran coronados con guirnaldas y liberados del trabajo durante el día." },
    "11-16": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "11-17": { status: 'NP', statusFull: "Saturnalia", deity: "Saturno", deityDesc: "El antiguo monarca divino agrario.", festivalName: "Saturnalia", festivalDesc: "¡Io Saturnalia! Comienza la festividad invernal de inversión de roles sociales, banquetes y goce hedonístico rememorando la Edad de Oro igualitaria." },
    "11-18": { status: 'C', statusFull: "Dies Comitialis", deity: "Saturno", deityDesc: "Dios regente.", festivalName: "Saturnalia", festivalDesc: "La ciudad queda inmersa en la entrega de pequeños obsequios (cerei y sigillaria) sin actividad judicial u hostil." },
    "11-19": { status: 'NP', statusFull: "Opalia", deity: "Ops", deityDesc: "Diosa de la providencia productiva.", festivalName: "Opalia / Saturnalia", festivalDesc: "Ofrendas consagradas a la consorte de Saturno celebrando la opulencia generada para sobrevivir las penurias." },
    "11-20": { status: 'C', statusFull: "Dies Comitialis", deity: "Saturno", deityDesc: "Rey de los dioses antiguos.", festivalName: "Saturnalia", festivalDesc: "El relajo civil absoluto prosigue. Elección tradicional en las familias del 'Rey del banquete'." },
    "11-21": { status: 'NP', statusFull: "Divalia", deity: "Angerona", deityDesc: "Diosa mística curativa y de los solsticios.", festivalName: "Divalia (Angeronalia) / Saturnalia", festivalDesc: "Celebración vinculada al solsticio con la boca de la efigie atada para exigir secreto en rituales apotropaicos y curativos invernales." },
    "11-22": { status: 'C', statusFull: "Dies Comitialis", deity: "Lares Permarini", deityDesc: "Espíritus del mar protector.", festivalName: "Saturnalia", festivalDesc: "Celebración adicional cívica por la dedicación republicana del altar a los Lares Permarini." },
    "11-23": { status: 'NP', statusFull: "Larentalia", deity: "Acca Larentia", deityDesc: "Loba nodriza o figura heroica legendaria asociada a los orígenes de Roma.", festivalName: "Larentalia", festivalDesc: "Parentatio independiente en la tumba de Acca Larentia en el Velabro, sin ninguna conexión con las Saturnales. El pontifex maximus oficiaba en el emplazamiento funerario de esta figura mítica —nodriza de Rómulo y Remo según unas tradiciones, cortesana enriquecida que legó sus bienes al pueblo romano según otras. El rito era un homenaje fúnebre, no una festividad invernal." },
    "11-24": { status: 'C', statusFull: "Dies Comitialis", deity: "Ninguna", deityDesc: "Día sin deidad específica." },
    "11-25": { status: 'C', statusFull: "Comitialis (calendario republicano)", deity: "Sol Invictus", deityDesc: "El Sol inquebrantable divino.", festivalName: "Dies Natalis Solis Invicti", festivalDesc: "Aprobada formalmente en tiempos de Aureliano, celebraba la victoria astronómica de la deidad y el retorno creciente de la luz solar anual tras el solsticio profundo." },
